+/** Theoretical use from sales vs actual consume movements between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const theo = new Map();
+  for (const s of store.data.sales ?? []) {
+    const day = dayOf(s.soldAt);
+    if (day < from || day > to) continue;
+    const dish = getDish(store, s.dishId);
+    const recipe = getRecipe(store, dish.recipeId);
+    for (const n of scaled(recipe, s.qty)) {
+      theo.set(n.itemId, (theo.get(n.itemId) ?? 0) + n.qty);
+    }
+  }
+
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const act = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    act.set(itemId, (act.get(itemId) ?? 0) + m.qty);
+  }
+
+  const lines = [];
+  for (const item of listItems(store)) {
+    const theoretical = round3(theo.get(item.id) ?? 0);
+    const actual = round3(act.get(item.id) ?? 0);
+    if (!(theoretical > 0 || actual > 0)) continue;
+    const diff = round3(actual - theoretical) || 0;
+    lines.push({ itemId: item.id, name: item.name, theoretical, actual, diff });
+  }
+  return lines;
+}
