diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..5d6c79e
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,69 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty). Already imported
+// tickets are skipped; any invalid row or stock shortage aborts the whole file.
+import { isIsoInstant } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getItem, onHand } from "../domain/items.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports till sales; returns { tickets, dishes } counts or throws naming the row. */
+export function importSales(store, text) {
+  const [head = [], ...rawRows] = parseCsv(text);
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) {
+    if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+  const rows = rawRows.map((r) => Object.fromEntries(keys.map((k, i) => [k, (r[i] ?? "").trim()])));
+
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isIsoInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = Number(r.dishId);
+    const dish = Number.isInteger(dishId) && dishId >= 1 ? (store.data.dishes ?? []).find((d) => d.id === dishId) : null;
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish` });
+    const qty = Number(r.qty);
+    if (!Number.isInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    const recipe = getRecipe(store, dish.recipeId);
+    return {
+      where,
+      ticket: r.ticket,
+      soldAt: new Date(Date.parse(r.soldAt)).toISOString(),
+      dishId,
+      qty,
+      needs: scaled(recipe, qty),
+    };
+  });
+
+  const imported = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const todo = clean.filter((c) => !imported.has(c.ticket));
+
+  const remaining = new Map();
+  for (const c of todo) {
+    for (const n of c.needs) {
+      if (n.qty <= 0) continue;
+      const item = getItem(store, n.itemId);
+      const available = Math.round((remaining.get(n.itemId) ?? onHand(store, n.itemId)) * 1000) / 1000;
+      if (available < n.qty) {
+        throw new AppError("not_enough_stock", { row: c.where, item: item.name, available, unit: item.unit });
+      }
+      remaining.set(n.itemId, Math.round((available - n.qty) * 1000) / 1000);
+    }
+  }
+
+  store.data.sales ??= [];
+  const tickets = new Set();
+  let dishes = 0;
+  for (const c of todo) {
+    for (const n of c.needs) {
+      if (n.qty > 0) consume(store, n.itemId, n.qty, { at: c.soldAt, ref: `sale:${c.ticket}` });
+    }
+    store.data.sales.push({ id: store.nextId("sale"), ticket: c.ticket, soldAt: c.soldAt, dishId: c.dishId, qty: c.qty });
+    tickets.add(c.ticket);
+    dishes += c.qty;
+  }
+  return { tickets: tickets.size, dishes };
+}
